// Signs release builds with the app's own upload key instead of the debug key
// the generated project uses. android/ is generated by `expo prebuild`, so this
// is done here (a config plugin) rather than by editing android/ by hand.
//
// The key itself never enters the repo: its location and passwords are Gradle
// properties, passed by scripts/build-apk.sh from a file kept next to the
// keystore. Without them (a development build), release falls back to the
// debug key, as before.
const { withAppBuildGradle } = require('expo/config-plugins');

const RELEASE_SIGNING = `
        release {
            if (project.hasProperty('FLEZEPAY_UPLOAD_STORE_FILE')) {
                storeFile file(FLEZEPAY_UPLOAD_STORE_FILE)
                storePassword FLEZEPAY_UPLOAD_STORE_PASSWORD
                keyAlias FLEZEPAY_UPLOAD_KEY_ALIAS
                keyPassword FLEZEPAY_UPLOAD_KEY_PASSWORD
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes('FLEZEPAY_UPLOAD_STORE_FILE')) return cfg;

    // Add a `release` signing config after the generated `debug` one.
    const debugBlock = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/;
    if (!debugBlock.test(gradle)) throw new Error('withReleaseSigning: signingConfigs.debug not found in app/build.gradle');
    gradle = gradle.replace(debugBlock, `$1${RELEASE_SIGNING}`);

    // Use it for release builds when the key is given.
    const releaseUsesDebug = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
    if (!releaseUsesDebug.test(gradle)) throw new Error('withReleaseSigning: release signingConfig not found in app/build.gradle');
    gradle = gradle.replace(
      releaseUsesDebug,
      "$1signingConfig project.hasProperty('FLEZEPAY_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug",
    );

    cfg.modResults.contents = gradle;
    return cfg;
  });
};
